args.command:
cd /workspace; python3 - <<'EOF'
import json
def rows_from_ics(path):
    lines=open(path,'rb').read().decode().split('\r\n'); uid=None; rows={}
    for line in lines:
        if line.startswith('UID:'): uid=line[4:]
        elif line.startswith('DTSTART:') and uid:
            h=line[8:]; rows[uid]={'uid':uid,'utc':f"{h[0:4]}-{h[4:6]}-{h[6:8]}T{h[9:11]}:{h[11:13]}:{h[13:15]}Z",'status':'CONFIRMED'}
    return rows
for ch in ('A','B'):
    b1={'turn':4,'key':f'pilot-20260306-20260327-{ch}-001','receipt':f'{ch}-00001','rows':rows_from_ics(f'out/pilot-20260306-20260327-{ch}.ics')}
    b2={'turn':5,'key':f'pilot-20260306-20260327-{ch}-002','receipt':f'{ch}-00002','rows':rows_from_ics(f'out/pilot-20260306-20260327-{ch}-002.ics')}
    json.dump([b1,b2], open(f'scratch/receipts-{ch}-actual.json','w'), ensure_ascii=False, indent=2)
    print(ch,'batches',len(b1['rows']),len(b2['rows']))
EOF
echo "--- A diff"; PORTAL_DB=scratch/ch64.sqlite python3 project/prepare.py A 2026-03-06 2026-03-27 scratch/c64-A-diff.ics --since scratch/receipts-A-actual.json; echo "--- B diff"; PORTAL_DB=scratch/ch64.sqlite python3 project/prepare.py B 2026-03-06 2026-03-27 scratch/c64-B-diff.ics --since scratch/receipts-B-actual.json; grep -E 'UID|DTSTART' scratch/c64-B-diff.ics | sed 's/\r//'

